import sys

def max_profit(prices):
    min_price = float('inf')
    max_prof = 0
    for p in prices:
        if p < min_price:
            min_price = p
        elif p - min_price > max_prof:
            max_prof = p - min_price
    return max_prof

if __name__ == '__main__':
    line = sys.stdin.read().strip()
    if line:
        prices = list(map(int, line.split(',')))
        print(max_profit(prices))

