import sys

def product_except_self(nums):
    n = len(nums)
    res = [1] * n
    prefix = 1
    for i in range(n):
        res[i] = prefix
        prefix *= nums[i]
    suffix = 1
    for i in range(n - 1, -1, -1):
        res[i] *= suffix
        suffix *= nums[i]
    return ','.join(map(str, res))

if __name__ == '__main__':
    line = sys.stdin.read().strip()
    if line:
        nums = list(map(int, line.split(',')))
        print(product_except_self(nums))

