import sys

def count_primes(n):
    if n <= 2: return 0
    is_prime = [True] * n
    is_prime[0] = is_prime[1] = False
    for p in range(2, int(n**0.5) + 1):
        if is_prime[p]:
            for multiple in range(p*p, n, p):
                is_prime[multiple] = False
    return sum(is_prime)

if __name__ == '__main__':
    line = sys.stdin.read().strip()
    if line:
        print(count_primes(int(line)))

